use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::Deserialize;
use std::ptr;
use std::slice;

#[derive(Deserialize)]
struct FirmwareUpdate {
    device_id: String,
    payload: String,
    checksum: String,
}

/// Process firmware chunk upload for IoT device fleet management
/// The payload is base64-encoded binary data that gets decoded into a fixed buffer
/// for checksum validation before forwarding to the device mesh
async fn upload_firmware_chunk(
    body: web::Json<FirmwareUpdate>,
) -> HttpResponse {
    // Fixed-size staging buffer for checksum computation
    // Device firmware chunks are contractually limited to 4KB by the device SDK
    let mut staging_buffer: [u8; 4096] = [0u8; 4096];

    let decoded = match base64::decode(&body.payload) {
        Ok(d) => d,
        Err(_) => return HttpResponse::BadRequest().body("Invalid base64 payload"),
    };

    // Validate device_id format (must be UUID-like)
    if body.device_id.len() != 36 {
        return HttpResponse::BadRequest().body("Invalid device ID format");
    }

    // VULNERABILITY: No bounds check on decoded length before unsafe copy
    // The developer assumed the device SDK enforces 4KB limit, but the API
    // endpoint is directly accessible
    unsafe {
        let src_ptr = decoded.as_ptr();
        let dst_ptr = staging_buffer.as_mut_ptr();
        // This copies decoded.len() bytes into a 4096-byte buffer
        // If decoded.len() > 4096, this overflows the stack buffer
        ptr::copy_nonoverlapping(src_ptr, dst_ptr, decoded.len());
    }

    // Compute simple checksum over the staging buffer
    let computed_checksum = compute_checksum(&staging_buffer, decoded.len().min(4096));

    if computed_checksum != body.checksum {
        return HttpResponse::BadRequest().body("Checksum mismatch");
    }

    // In production this would forward to device mesh via gRPC
    HttpResponse::Ok().json(serde_json::json!({
        "status": "accepted",
        "device_id": body.device_id,
        "bytes_processed": decoded.len().min(4096)
    }))
}

fn compute_checksum(buffer: &[u8], len: usize) -> String {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    let mut hasher = DefaultHasher::new();
    buffer[..len].hash(&mut hasher);
    format!("{:016x}", hasher.finish())
}

/// Health check endpoint used by load balancer
async fn health() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

/// Metrics endpoint - exposes Prometheus-compatible metrics
async fn metrics() -> HttpResponse {
    HttpResponse::Ok()
        .content_type("text/plain")
        .body("# HELP firmware_chunks_total Total firmware chunks processed\nfirmware_chunks_total 0\n")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health))
            .route("/metrics", web::get().to(metrics))
            .route("/api/v2/firmware/chunk", web::post().to(upload_firmware_chunk))
            .app_data(web::JsonConfig::default().limit(1048576)) // 1MB JSON limit
    })
    .bind("0.0.0.0:8080")?
    .workers(4)
    .run()
    .await
}
